1	//! Agent-facing output: TOON projections of command results and conversion of [`MonoklError`] into michi errors.
2	use michi::toon::Value;
3	
4	use crate::error::MonoklError;
5	use crate::types::{SymbolKind, Visibility};
6	
7	/// The CLI command currently executing, so a recovery hint can name the right tool to retry.
8	pub struct ErrorContext<'a> {
9	    pub command: &'a str,
10	}
11	
12	/// Converts a string into a TOON cell value.
13	///
14	/// The string is passed through unchanged: michi quotes and escapes control characters when it renders the row, so
15	/// escaping here as well would double-escape them.
16	pub fn cell(s: &str) -> Value {
17	    Value::from(s)
18	}
19	
20	/// Like [`cell`], but maps `None` to [`Value::Null`].
21	pub fn opt_cell(s: Option<&str>) -> Value {
22	    match s {
23	        None => Value::Null,
24	        Some(s) => cell(s),
25	    }
26	}
27	
