61	/// Returns the same `camelCase` name that serde produces for a [`SymbolKind`].
62	pub fn symbol_kind_str(k: SymbolKind) -> &'static str {
63	    match k {
64	        SymbolKind::Function => "function",
65	        SymbolKind::Method => "method",
66	        SymbolKind::Constructor => "constructor",
67	        SymbolKind::Class => "class",
68	        SymbolKind::Struct => "struct",
69	        SymbolKind::Enum => "enum",
70	        SymbolKind::Interface => "interface",
71	        SymbolKind::TypeAlias => "typeAlias",
72	        SymbolKind::Property => "property",
73	        SymbolKind::Field => "field",
74	        SymbolKind::Variable => "variable",
75	        SymbolKind::Module => "module",
76	        SymbolKind::Impl => "impl",
77	        SymbolKind::Macro => "macro",
78	        SymbolKind::Other => "other",
79	    }
80	}
81	
82	/// Returns the same `camelCase` name that serde produces for a [`Visibility`].
83	pub fn visibility_str(v: Visibility) -> &'static str {
84	    match v {
85	        Visibility::Public => "public",
86	        Visibility::Crate => "crate",
87	        Visibility::Module => "module",
88	        Visibility::Private => "private",
89	    }
90	}
