236	    #[test]
237	    fn render_projection_symbols_result_end_to_end() {
238	        use crate::types::{SymbolEntry, SymbolKind, SymbolsResult};
239	        use camino::Utf8PathBuf;
240	        use std::collections::BTreeMap;
241	
242	        let mut files = BTreeMap::new();
243	        files.insert(
244	            Utf8PathBuf::from("src/lib.rs"),
245	            vec![SymbolEntry {
246	                name: "foo".to_string(),
247	                kind: SymbolKind::Function,
248	                line: 10,
249	                // The newline must render as the escape `\n` inside a quoted cell, neither breaking the row nor vanishing.
250	                signature: Some("fn foo(x)\nsecond line".to_string()),
251	                // Distinct values in every optional column, so a hardcoded `Value::Null` for any of them shows up.
252	                owner: Some("MyOwner".to_string()),
253	                trait_impl: Some("MyTrait".to_string()),
254	                visibility: Some(crate::types::Visibility::Public),
255	                kind_detail: Some("static".to_string()),
256	            }],
257	        );
258	        let result = SymbolsResult { files, total_symbol_count: 1, truncation_marker: None, diagnostics: Vec::new() };
259	
260	        let rendered = render_projection(&result).expect("valid projection must render");
261	        assert!(
262	            rendered.starts_with("symbols[1]{file,name,kind,line,signature,owner,traitImpl,visibility,kindDetail}:\n"),
263	            "got: {rendered}"
264	        );
265	        assert!(
266	            rendered.contains("src/lib.rs,foo,function,10,\"fn foo(x)\\nsecond line\",MyOwner,MyTrait,public,static"),
267	            "got: {rendered}"
268	        );
269	    }
